UPDATE merchant_goods
merchant_base_id = #{merchantBaseId}, goods_name = #{goodsName}, category = #{category}, sub_category = #{subCategory}, price = #{price}, original_price = #{originalPrice}, stock = #{stock}, sales_count = #{salesCount}, description = #{description}, tag_codes = #{tagCodes}, status = #{status}, avg_rating = #{avgRating}, rating_count = #{ratingCount}, five_star_rate = #{fiveStarRate}, four_star_rate = #{fourStarRate}, three_star_rate = #{threeStarRate}, two_star_rate = #{twoStarRate}, one_star_rate = #{oneStarRate}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET status = #{status}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET stock = #{stock}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET sales_count = sales_count + #{count}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId}

UPDATE merchant_goods
SET stock = stock - #{count}, update_time = NOW()
WHERE merchant_goods_id = #{merchantGoodsId} AND stock >= #{count}

